        if len(graph[i]) == 1:
            roots.append(i)

    if len(roots) < 3:
        return 'NO'

    visited = [False] * (n + 1)
    cycle_length = 0

    def dfs(node, parent):
        nonlocal cycle_length
        visited[node] = True
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if visited[neighbor]:
                cycle_length = len(graph[node])
                return True
            if dfs(neighbor, node):
                return True
        visited[node] = False
        return False

